'use client'

import { useState, useRef, useEffect } from 'react'
import Link from 'next/link'
import SignOutButton from './SignOutButton'
import ThemeToggleButton from './ThemeToggleButton'
import FeedbackButton from './FeedbackButton'

export default function HeaderMenu({ 
  isLoggedIn, 
  canManage, 
  showDailyReports,
  isSiteAdmin,
  roleLevel,
  isInBand // <--- NEW PROP
}: { 
  isLoggedIn: boolean
  canManage: boolean
  showDailyReports: boolean
  isSiteAdmin: boolean
  roleLevel: number
  isInBand: boolean // <--- TYPE
}) {
  const [isOpen, setIsOpen] = useState(false)
  const menuRef = useRef<HTMLDivElement>(null)

  useEffect(() => {
    function handleClickOutside(event: MouseEvent) {
      if (menuRef.current && !menuRef.current.contains(event.target as Node)) {
        setIsOpen(false)
      }
    }
    document.addEventListener("mousedown", handleClickOutside)
    return () => document.removeEventListener("mousedown", handleClickOutside)
  }, [menuRef])

  if (!isLoggedIn) {
    return (
      <div className="flex items-center gap-4">
        <ThemeToggleButton />
        <Link href="/login" className="text-sm font-medium text-foreground hover:text-primary transition-colors">
          Log in
        </Link>
      </div>
    )
  }

  return (
    <div className="relative flex items-center gap-2" ref={menuRef}>
      <ThemeToggleButton />
      <FeedbackButton />
      
      {/* Desktop Menu */}
      <div className="hidden md:flex items-center gap-4 ml-4">
        {/* BAND LINK: Visible if in band OR faculty (roleLevel >= 50) */}
        {(isInBand || roleLevel >= 50) && (
           <Link href="/band" className="text-sm font-medium text-foreground hover:text-primary transition-colors">
             Band
           </Link>
        )}

        <Link href="/" className="text-sm font-medium text-foreground hover:text-primary transition-colors">
          Dashboard
        </Link>
        {canManage && (
          <Link href="/manage" className="text-sm font-medium text-foreground hover:text-primary transition-colors">
            Rosters
          </Link>
        )}
        {showDailyReports && (
           <Link href="/reports/daily" className="text-sm font-medium text-foreground hover:text-primary transition-colors">
             Daily
           </Link>
        )}
        {isSiteAdmin && (
           <Link href="/admin" className="text-sm font-medium text-destructive hover:text-destructive/80 transition-colors">
             Admin
           </Link>
        )}
        <div className="h-4 w-px bg-border mx-2"></div>
        <SignOutButton />
      </div>

      {/* Mobile Menu Button */}
      <button 
        onClick={() => setIsOpen(!isOpen)}
        className="md:hidden p-2 rounded-md text-foreground hover:bg-muted focus:outline-none"
      >
        <span className="sr-only">Open menu</span>
        {isOpen ? (
          <svg className="h-6 w-6" fill="none" viewBox="0 0 24 24" stroke="currentColor">
            <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M6 18L18 6M6 6l12 12" />
          </svg>
        ) : (
          <svg className="h-6 w-6" fill="none" viewBox="0 0 24 24" stroke="currentColor">
            <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M4 6h16M4 12h16M4 18h16" />
          </svg>
        )}
      </button>

      {/* Mobile Dropdown */}
      {isOpen && (
        <div className="absolute right-0 top-12 w-48 py-1 rounded-md shadow-lg bg-popover border border-border ring-1 ring-black ring-opacity-5 z-50 animate-in fade-in zoom-in-95 duration-100">
          <Link href="/" className="block px-4 py-2 text-sm text-foreground hover:bg-muted" onClick={() => setIsOpen(false)}>
            Dashboard
          </Link>
          
          {/* Mobile Band Link */}
          {(isInBand || roleLevel >= 50) && (
            <Link href="/band" className="block px-4 py-2 text-sm text-foreground hover:bg-muted" onClick={() => setIsOpen(false)}>
              Band Roster
            </Link>
          )}

          {canManage && (
            <Link href="/manage" className="block px-4 py-2 text-sm text-foreground hover:bg-muted" onClick={() => setIsOpen(false)}>
              Manage Rosters
            </Link>
          )}
          {showDailyReports && (
            <Link href="/reports/daily" className="block px-4 py-2 text-sm text-foreground hover:bg-muted" onClick={() => setIsOpen(false)}>
              Daily Reports
            </Link>
          )}
          {isSiteAdmin && (
            <Link href="/admin" className="block px-4 py-2 text-sm text-destructive hover:bg-destructive/10" onClick={() => setIsOpen(false)}>
              Admin Settings
            </Link>
          )}
          <div className="border-t border-border my-1"></div>
          <div className="px-4 py-2">
            <SignOutButton />
          </div>
        </div>
      )}
    </div>
  )
}